import { Clock } from 'lucide-react'
import { useRepo } from '@/context/repo.js'
import { useBlockContext } from '@/context/block.js'
import {
  mapNavigate,
  navigate,
  resolveNavigationIntent,
  type BlockLinkClickModifierState,
} from '@/utils/navigation.js'
import { isMobileViewport } from '@/utils/viewport.js'
import { getOrCreateRecentsPage } from '@/data/recentsPage.js'

// Intent resolution never depends on the target `blockId` — only on the
// role/modifiers/viewport/panel — so a placeholder here resolves the exact
// same routing decision the real (async-resolved) Recents-page id would.
// See `resolveNavigationIntent`'s docblock in navigation.ts.
const PROBE_BLOCK_ID = ''

export function RecentsHeaderItem() {
  const repo = useRepo()
  const {panelId} = useBlockContext()

  return (
    <button
      className="inline-flex h-7 w-7 items-center justify-center rounded-md p-0 text-sm text-muted-foreground transition-colors hover:text-foreground sm:h-8 sm:w-8"
      onClick={event => {
        const workspaceId = repo.activeWorkspaceId
        if (!workspaceId) return

        // The Recents page id is only known after resolving live state
        // (`getOrCreateRecentsPage`, async — issue #378 means the raw
        // deterministic id can be a tombstone). But preventDefault/
        // stopPropagation, and the click's modifier semantics (shift/alt/
        // native-passthrough), must be decided synchronously, in THIS
        // dispatch — not after an `await`, by which point any ancestor
        // handler in the same click has already run and the browser's
        // default action can no longer be cancelled. So: capture the
        // modifier state and resolve the navigation decision now, using a
        // placeholder blockId (intent resolution doesn't look at it), then
        // patch in the real id and execute once it resolves.
        const modifiers: BlockLinkClickModifierState = {
          shiftKey: event.shiftKey,
          altKey: event.altKey,
          metaKey: event.metaKey,
          ctrlKey: event.ctrlKey,
          button: event.button,
        }
        const decision = resolveNavigationIntent(repo, {
          role: 'navigator',
          modifiers,
          panelId,
          blockId: PROBE_BLOCK_ID,
          workspaceId,
          viewport: isMobileViewport() ? 'mobile' : 'desktop',
        })
        // No `href` on this button, so passthrough (native modifier click)
        // is simply "do nothing" — matches `useBlockOpener` on a plain click.
        if (decision.kind === 'passthrough') return
        event.stopPropagation()
        event.preventDefault()
        if (decision.kind === 'suppress') return // vetoed by a plugin

        void (async () => {
          const page = await getOrCreateRecentsPage(repo, workspaceId)
          const resolved = mapNavigate(decision, input => ({...input, blockId: page.id}))
          if (resolved.kind === 'navigate') await navigate(repo, resolved.input)
        })()
      }}
      title="Recently edited blocks"
      aria-label="Open recents"
    >
      <Clock className="h-4 w-4"/>
    </button>
  )
}
